apply_patch <<'PATCH'
*** Begin Patch
*** Add File: server.js
+import { createServer } from 'node:http';
+import { randomUUID } from 'node:crypto';
+import { readFile, rename, writeFile } from 'node:fs/promises';
+import { dirname, join } from 'node:path';
+import { fileURLToPath } from 'node:url';
+
+const root = dirname(fileURLToPath(import.meta.url));
+const dataFile = join(root, 'data', 'books.json');
+const publicDir = join(root, 'public');
+const port = Number(process.env.PORT || 3000);
+const assets = new Map([
+  ['/styles.css', ['styles.css', 'text/css; charset=utf-8']],
+  ['/app.js', ['app.js', 'text/javascript; charset=utf-8']],
+]);
+
+let writeQueue = Promise.resolve();
+
+async function readBooks() {
+  try {
+    const data = await readFile(dataFile, 'utf8');
+    const books = JSON.parse(data);
+    return Array.isArray(books) ? books : [];
+  } catch (error) {
+    if (error.code === 'ENOENT') return [];
+    throw error;
+  }
+}
+
+function updateBooks(update) {
+  const operation = writeQueue.then(async () => {
+    const books = await readBooks();
+    const result = update(books);
+    const tempFile = "'`${dataFile}.${process.pid}.tmp`;
+    await writeFile(tempFile, `${JSON.stringify(books, null, 2)}'"\\n"'`, '"'utf8');
+    await rename(tempFile, dataFile);
+    return result;
+  });
+  writeQueue = operation.catch(() => {});
+  return operation;
+}
+
+function sendJson(response, status, payload) {
+  response.writeHead(status, {
+    'Content-Type': 'application/json; charset=utf-8',
+    'Cache-Control': 'no-store',
+  });
+  response.end(JSON.stringify(payload));
+}
+
+async function readBody(request) {
+  let body = '';
+  for await (const chunk of request) {
+    body += chunk;
+    if (body.length > 1_000_000) {
+      const error = new Error('Request body is too large.');
+      error.status = 413;
+      throw error;
+    }
+  }
+  try {
+    return JSON.parse(body || '{}');
+  } catch {
+    const error = new Error('Please send valid JSON.');
+    error.status = 400;
+    throw error;
+  }
+}
+
+async function handleApi(request, response, url) {
+  if (url.pathname === '/api/books' && request.method === 'GET') {
+    return sendJson(response, 200, await readBooks());
+  }
+
+  if (url.pathname === '/api/books' && request.method === 'POST') {
+    const body = await readBody(request);
+    const title = typeof body.title === 'string' ? body.title.trim() : '';
+    const author = typeof body.author === 'string' ? body.author.trim() : '';
+    const notes = typeof body.notes === 'string' ? body.notes.trim() : '';
+    if ("'!title || !author) {
+      return sendJson(response, 400, { error: '"'Title and author are required.' });
+    }
+    if (title.length > 200 || author.length > 160 || notes.length > 5000) {
+      return sendJson(response, 400, { error: 'One or more fields are too long.' });
+    }
+
+    const book = {
+      id: randomUUID(),
+      title,
+      author,
+      notes,
+      status: 'reading',
+      createdAt: new Date().toISOString(),
+      finishedAt: null,
+    };
+    await updateBooks((books) => books.unshift(book));
+    return sendJson(response, 201, book);
+  }
+
+  const match = url.pathname.match(/"'^'"\\/api\\/books\\/(["'^/]+)$/);
+  if (match && request.method === '"'PATCH') {
+    const body = await readBody(request);
+    if (body.status "'!== '"'finished') {
+      return sendJson(response, 400, { error: 'The only supported update is marking a book finished.' });
+    }
+    const result = await updateBooks((books) => {
+      const book = books.find((item) => item.id === match[1]);
+      if ("'!book) return null;
+      book.status = '"'finished';
+      book.finishedAt ||= new Date().toISOString();
+      return book;
+    });
+    if ("'!result) return sendJson(response, 404, { error: '"'Book not found.' });
+    return sendJson(response, 200, result);
+  }
+
+  return sendJson(response, 404, { error: 'Not found.' });
+}
+
+async function handleRequest(request, response) {
+  const url = new URL(request.url, "'`http://${request.headers.host || '"'localhost'}"'`);
+  try {
+    if (url.pathname.startsWith('"'/api/')) {
+      return await handleApi(request, response, url);
+    }
+
+    if (request.method "'!== '"'GET' && request.method "'!== '"'HEAD') {
+      response.writeHead(405, { Allow: 'GET, HEAD' });
+      return response.end('Method not allowed.');
+    }
+
+    const asset = assets.get(url.pathname);
+    if (asset) {
+      const content = await readFile(join(publicDir, asset[0]));
+      response.writeHead(200, {
+        'Content-Type': asset[1],
+        'Cache-Control': 'no-cache',
+      });
+      return response.end(request.method === 'HEAD' ? undefined : content);
+    }
+
+    if (url.pathname === '/' || url.pathname.startsWith('/book/')) {
+      const content = await readFile(join(publicDir, 'index.html'));
+      response.writeHead(200, {
+        'Content-Type': 'text/html; charset=utf-8',
+        'Cache-Control': 'no-cache',
+      });
+      return response.end(request.method === 'HEAD' ? undefined : content);
+    }
+
+    response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+    return response.end('Not found.');
+  } catch (error) {
+    if (url.pathname.startsWith('/api/')) {
+      return sendJson(response, error.status || 500, { error: error.status ? error.message : 'Something went wrong.' });
+    }
+    response.writeHead(500, { 'Content-Type': 'text/plain; charset=utf-8' });
+    return response.end('Something went wrong.');
+  }
+}
+
+createServer(handleRequest).listen(port, () => {
+  console.log("'`Reading journal is ready at http://localhost:${port}`);
+});
*** End Patch
